SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state", "n_short", "n_price", "n_due", 'hold_ar' AS "route", 'overdue invoices' AS "verdict_reason"
FROM (SELECT "t28"."order_number", "t28"."customer", "t28"."channel", "t28"."fulfilling_warehouse", "t28"."value", "t28"."placed_date", "t28"."state", COALESCE("t28"."n_short", 0) AS "n_short", COALESCE("t28"."n_price", 0) AS "n_price", COALESCE("t34"."n_due", 0) AS "n_due"
        FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "t16"."n_short", "t27"."n_price"
                FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "t15"."n_short"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t10"."line_no", "t10"."item", "t10"."quantity", "t10"."unit_price", "t10"."ext_sales_price", "t10"."warehouse", "t10"."sold_date", "t10"."customer0", "t10"."channel0", "t10"."as_of_date", "t10"."quantity_on_hand", "t10"."_ttrp_g_n9_0", "t10"."_ttrp_g_n9_1", "t11"."warehouse" AS "warehouse0", "t11"."from_date", "t11"."to_date", "t11"."reason", COALESCE("t10"."quantity_on_hand", 0) AS "on_hand", "t11"."warehouse" IS NOT NULL AS "outage"
                                        FROM (SELECT "t4"."order_number", "t4"."customer", "t4"."channel", "t4"."fulfilling_warehouse", "t4"."value", "t4"."placed_date", "t4"."state", "t4"."line_no", "t4"."item", "t4"."quantity", "t4"."unit_price", "t4"."ext_sales_price", "t4"."warehouse", "t4"."sold_date", "t4"."customer0", "t4"."channel0", "t4"."as_of_date", "t4"."quantity_on_hand", "t4"."_ttrp_g_n9_0", "t4"."_ttrp_g_n9_1"
                                                FROM (SELECT "t3"."order_number", "t3"."customer", "t3"."channel", "t3"."fulfilling_warehouse", "t3"."value", "t3"."placed_date", "t3"."state", "t3"."line_no", "t3"."item", "t3"."quantity", "t3"."unit_price", "t3"."ext_sales_price", "t3"."warehouse", "t3"."sold_date", "t3"."customer0", "t3"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t3"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t3"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t3"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t3"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                        FROM (SELECT "t2"."order_number", "t2"."customer", "t2"."channel", "t2"."fulfilling_warehouse", "t2"."value", "t2"."placed_date", "t2"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t2"
                                                                    INNER JOIN "sales_line" ON "t2"."order_number" = "sales_line"."order_number") AS "t3"
                                                            LEFT JOIN "inventory" ON "t3"."item" = "inventory"."item" AND "t3"."warehouse" = "inventory"."warehouse") AS "t4"
                                                    INNER JOIN (SELECT CASE WHEN "t7"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t7"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                                        FROM (SELECT "t6"."order_number", "t6"."customer", "t6"."channel", "t6"."fulfilling_warehouse", "t6"."value", "t6"."placed_date", "t6"."state", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."quantity", "sales_line0"."unit_price", "sales_line0"."ext_sales_price", "sales_line0"."warehouse", "sales_line0"."sold_date", "sales_line0"."customer" AS "customer0", "sales_line0"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t6"
                                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t6"."order_number" = "sales_line0"."order_number") AS "t7"
                                                            LEFT JOIN "inventory" AS "inventory0" ON "t7"."item" = "inventory0"."item" AND "t7"."warehouse" = "inventory0"."warehouse"
                                                        GROUP BY CASE WHEN "t7"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."order_number" AS VARCHAR) END, CASE WHEN "t7"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t7"."line_no" AS VARCHAR) END) AS "t9" ON "t4"."_ttrp_g_n9_0" = "t9"."_ttrp_g_n9_0" AND "t4"."_ttrp_g_n9_1" = "t9"."_ttrp_g_n9_1" AND "t4"."as_of_date" = "t9"."_ttrp_latest_n9") AS "t10"
                                            LEFT JOIN (SELECT *
                                                FROM "warehouse_outage"
                                                WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t11" ON "t10"."warehouse" = "t11"."warehouse") AS "t12"
                                WHERE "t12"."outage" OR "t12"."on_hand" < "t12"."quantity"
                                GROUP BY "order_number") AS "t15" ON "t0"."order_number" = "t15"."order_number") AS "t16"
                    LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                        FROM (SELECT "t19"."order_number", "t19"."line_no", "t19"."item", "t19"."unit_price", "t19"."customer", "t19"."channel", "t19"."placed_date", "t23"."order_number" AS "order_number0", "t23"."line_no" AS "line_no0", "t23"."price"
                                FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t18"."customer", "t18"."channel", "t18"."placed_date"
                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                FROM "order"
                                                WHERE "state" IN ('held', 'placed')) AS "t18"
                                            INNER JOIN "sales_line" AS "sales_line1" ON "t18"."order_number" = "sales_line1"."order_number") AS "t19"
                                    INNER JOIN (SELECT "t22"."order_number", "t22"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                        FROM (SELECT "sales_line2"."order_number", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."unit_price", "t21"."customer", "t21"."channel", "t21"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t21"
                                                    INNER JOIN "sales_line" AS "sales_line2" ON "t21"."order_number" = "sales_line2"."order_number") AS "t22"
                                            LEFT JOIN "customer_price" ON "t22"."item" = "customer_price"."item" AND "t22"."customer" = "customer_price"."customer" AND "t22"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t22"."placed_date" <= "customer_price"."valid_to")
                                            LEFT JOIN "price_list" ON "t22"."item" = "price_list"."item" AND "t22"."channel" = "price_list"."channel" AND "t22"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t22"."placed_date" <= "price_list"."valid_to")) AS "t23" ON "t19"."order_number" = "t23"."order_number" AND "t19"."line_no" = "t23"."line_no") AS "t24"
                        WHERE "t24"."price" IS NULL OR ABS("t24"."unit_price" - "t24"."price") > :tolerance
                        GROUP BY "order_number0") AS "t27" ON "t16"."order_number" = "t27"."order_number") AS "t28"
            LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                FROM (SELECT "t30"."order_number", "t30"."customer", "t30"."channel", "t30"."fulfilling_warehouse", "t30"."value", "t30"."placed_date", "t30"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t30"
                            INNER JOIN "invoice" ON "t30"."customer" = "invoice"."customer") AS "t31"
                WHERE "t31"."status" = 'open' AND "t31"."due" < :as_of
                GROUP BY "order_number") AS "t34" ON "t28"."order_number" = "t34"."order_number") AS "t35"
WHERE "t35"."n_due" > 0
